 1	lemma SkippingLemma(a : array<int>, j : int)
 2	   requires a != null
 3	   requires forall i :: 0 <= i < a.Length ==> 0 <= a[i]
 4	   requires forall i :: 0 < i < a.Length ==> a[i-1]-1 <= a[i]
 5	   requires 0 <= j < a.Length
 6	   ensures forall k :: j <= k < (j + a[j]) + 1 && k < a.Length ==> a[k] != 0
 7	{
 8	   var i := j;
 9	   while i < j + a[j] && i < a.Length
10	   decreases j + a[j] - i
11	      invariant i < a.Length ==> a[j] - (i-j) <= a[i]
12	      invariant forall k :: j <= k < i && k < a.Length ==> a[k] != 0
13	   {
14	      i := i + 1;
15	   }
16	}
17	method FindZero(a: array<int>) returns (index: int)
18	   requires a != null
19	   requires forall i :: 0 <= i < a.Length ==> 0 <= a[i]
20	   requires forall i :: 0 < i < a.Length ==> a[i-1]-1 <= a[i]
21	   ensures index < 0  ==> forall i :: 0 <= i < a.Length ==> a[i] != 0
22	   ensures 0 <= index ==> index < a.Length && a[index] == 0
23	{
24	   index := 0;
25	   while index < a.Length
26	   decreases a.Length - index
27	      invariant 0 <= index
28	      invariant forall k :: 0 <= k < index && k < a.Length ==> a[k] != 0
29	   {
30	      if a[index] == 0 { return; }
31	      SkippingLemma(a, index);
32	      index := index + a[index];
33	   }
34	   index := -1;
35	}
36

